# generated by tools/ail2py.py from csv_stream_main.ail; edit the .ail until onelang s16
from csv_stream import *
from utf8_stream import *
from checked_integer import *
from ail import file_chunks, write_stdout_bytes
import sys

# Complete rows are emitted as they arrive; later input errors can leave rows on stdout.
def main() -> int:
    if len(sys.argv) != 3:
        print('usage: csv_stream INPUT SIZE', file=sys.stderr)
        return 2
    try:
        size: int = parse_int64_decimal(sys.argv[2])
        if size <= 0:
            raise ValueError
        utf8 = utf8_decoder_new()
        csv: CsvDecoder = csv_decoder_new()
        for chunk in file_chunks(sys.argv[1], size):
            rows = csv_decode_feed(csv, utf8_decode_feed(utf8, chunk))
            for row in rows:
                write_stdout_bytes((csv_stream_row_json(row) + '\n').encode())
        tail = csv_decode_feed(csv, utf8_decode_finish(utf8))
        for row in tail:
            write_stdout_bytes((csv_stream_row_json(row) + '\n').encode())
        final = csv_decode_finish(csv)
        for row in final:
            write_stdout_bytes((csv_stream_row_json(row) + '\n').encode())
        return 0
    except ValueError:
        print('invalid UTF-8, CSV, or chunk size', file=sys.stderr)
        return 2
    except OSError:
        print('CSV stream input or output failed', file=sys.stderr)
        return 2
    return 0

if __name__ == "__main__":
    sys.exit(main())
